var formulario = document.getElementById("formulario");

formulario.addEventListener("submit", function(event) {

    event.preventDefault();

    var modelo = document.getElementById("modelo").value;
    var precio = document.getElementById("precio").value;
    var nombre = document.getElementById("nombre").value;
    var telefono = document.getElementById("telefono").value;

    var datos = new URLSearchParams();

    datos.append("modelo", modelo);
    datos.append("precio", precio);
    datos.append("nombre", nombre);
    datos.append("telefono", telefono);

    fetch("URL_DE_APPS_SCRIPT", {
        method: "POST",
        mode: "no-cors",
        body: datos
    });

    alert("Venta guardada");
});

function iniciarSesion() {

    var usuario = document.getElementById("usuario").value;
    var contrasena = document.getElementById("contrasena").value;

    if (usuario == "admin" && contrasena == "1234") {

        window.location.href = "administrador/index.html";

    } else {

        document.getElementById("mensaje").innerHTML =
            "Usuario o contraseña incorrectos";
    }
}

var url = "URL_DE_APPS_SCRIPT";

fetch(url)
    .then(function(respuesta) {

        return respuesta.json();

    })
    .then(function(datos) {

        mostrarVentas(datos);

    });

function mostrarVentas(datos) {

    var tabla = document.getElementById("tablaVentas");

    var totalVentas = 0;
    var totalDinero = 0;

    for (var i = 1; i < datos.length; i++) {

        var modelo = datos[i][0];
        var precio = datos[i][1];
        var nombre = datos[i][2];
        var telefono = datos[i][3];

        tabla.innerHTML +=
            "<tr>" +
                "<td>" + modelo + "</td>" +
                "<td>$" + precio + "</td>" +
                "<td>" + nombre + "</td>" +
                "<td>" + telefono + "</td>" +
            "</tr>";

        totalVentas = totalVentas + 1;

        totalDinero = totalDinero + Number(precio);
    }

    document.getElementById("totalVentas").innerHTML =
        totalVentas;

    document.getElementById("totalDinero").innerHTML =
        "$" + totalDinero;
}

function doPost(e) {

    var hoja = SpreadsheetApp
        .getActiveSpreadsheet()
        .getSheetByName("Ventas");

    var modelo = e.parameter.modelo;
    var precio = e.parameter.precio;
    var nombre = e.parameter.nombre;
    var telefono = e.parameter.telefono;

    hoja.appendRow([
        modelo,
        precio,
        nombre,
        telefono
    ]);

    return ContentService.createTextOutput("Venta guardada");
}

function doGet(e) {

    var hoja = SpreadsheetApp
        .getActiveSpreadsheet()
        .getSheetByName("Ventas");

    var datos = hoja
        .getDataRange()
        .getValues();

    return ContentService
        .createTextOutput(JSON.stringify(datos))
        .setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
    var hoja = SpreadsheetApp
        .getActiveSpreadsheet()
        .getSheetByName("Ventas");

    var modelo = e.parameter.modelo;
    var precio = e.parameter.precio;
    var cliente = e.parameter.cliente;

    hoja.appendRow([
        modelo,
        precio,
        cliente
    ]);

    return ContentService.createTextOutput("Venta guardada");
